"""Build the finance/insurance analytical-case research candidates.

The compact catalogue below is the maintained source.  The generated JSONL conforms to the
shared industry research schema.  Cases deliberately describe questions and decisions rather
than treating a metric, score, report, or model output as an analytical case.
"""

from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parent
INDUSTRY = "industry.finance_insurance"

