def main() -> None:
    ids = [item["record_id"] for item in cases]
    if len(ids) != len(set(ids)):
        raise SystemExit("duplicate analytical case id")
    target = ROOT / "analytics-cases.jsonl"
    text = "\n".join(json.dumps(item, separators=(",", ":"), ensure_ascii=False) for item in cases) + "\n"
    target.write_text(text, encoding="utf-8")
    print(f"wrote {len(cases)} analytical cases to {target}")


if __name__ == "__main__":
    main()
